import fs from 'node:fs';
import assert from 'node:assert/strict';

const route = fs.readFileSync(new URL('../app/api/cron/run-automations/route.js', import.meta.url), 'utf8');

const must = (text, message) => assert(route.includes(text), message);
const mustNot = (text, message) => assert(!route.includes(text), message);

// Separate product-image typography must now be generated by GPT Image 2 as
// genuine alpha transparency rather than a locally rendered glass card.
must('async function createTransparentProductTypographyOverlay({', 'Static transparent typography helper is missing.');
must('provider: "gpt-image-2-transparent-typography"', 'GPT Image typography provider marker is missing.');
must('background: "transparent"', 'GPT Image calls must request real transparent output.');
must('Every pixel that is not part of the typography', 'Static typography prompt must explicitly require alpha transparency.');
must('No card, panel, badge, sticker, label background', 'Static typography prompt must explicitly forbid label backgrounds.');
must('websiteItem: slideProduct', 'Carousel renderer must receive exact product identity context.');
must('websiteItem,\n              productTitle: singleProductPresentation.title', 'Single-product renderer must receive exact product identity context.');
must('openai,\n          supabase,\n          rule,', 'Carousel renderer must receive OpenAI so GPT typography can run.');
mustNot('fill-opacity="0.78"', 'Legacy translucent glass product-card styling must be removed.');
mustNot('compact_card', 'Legacy compact-card layout must not remain available.');

// Product isolation should reuse an existing alpha channel first, and only call
// GPT Image when the placement analysis recommends a cutout for this image.
must('cutout_recommended', 'Image analysis must return a cutout recommendation.');
must('productLabelAnalysis?.cutoutRecommended === true', 'Static AI product isolation must be gated by the recommendation.');
must('async function createGptImageProductTransparentCutout({', 'Verified GPT Image product cutout helper is missing.');
must('Understand the image first, then isolate ONLY the physical product', 'Product cutout prompt must identify only the sold product.');
must('Every background pixel must be truly transparent alpha', 'Product cutout must require real alpha transparency.');
must('reviewAnimatedProductTransparentIdentity', 'AI-edited product cutouts must retain an identity review.');
must('gpt_image_2_transparent_cutout', 'Accepted transparent product cutouts must be explicitly marked.');

// Animated product Reels must use the same no-panel typography concept.
must('Create ONLY a transparent typography asset for a premium 9:16 product Reel.', 'Reel typography prompt was not converted to transparent output.');
must('No card, panel, badge, sticker, banner, rectangle, capsule', 'Reel prompt must forbid opaque typography panels.');
must('Generated Reel typography contained an opaque card or excessive background area', 'Reel alpha validation must reject panel-like outputs.');
must('provider: "fallback_text_only_typography"', 'Reel emergency fallback must remain text-only.');

// AI product ads already generate a complete final image including text, so
// they must remain their own full-image generation path rather than receiving
// an extra overlay after generation.
must('export async function generateWebsiteItemAdImage(openai, rule, postContent)', 'AI product-ad generation path is missing.');
must('Include readable marketing text in the image.', 'AI product ads must continue generating their integrated text in one image.');
const adStart = route.indexOf('export async function generateWebsiteItemAdImage(openai, rule, postContent)');
const adEnd = route.indexOf('export async function generateAutomationImage', adStart);
assert(adStart >= 0 && adEnd > adStart, 'Could not isolate AI product-ad function.');
const adSlice = route.slice(adStart, adEnd);
assert(!adSlice.includes('createTransparentProductTypographyOverlay'), 'AI product ads must not receive an additional transparent text overlay.');


const adminProductRegenerate = fs.readFileSync(new URL('../app/api/admin/post-approvals/regenerate-product/route.js', import.meta.url), 'utf8');
const adminCarouselRegenerate = fs.readFileSync(new URL('../app/api/admin/post-approvals/regenerate/route.js', import.meta.url), 'utf8');
assert(adminProductRegenerate.includes('sourceImageUrl: lockedProduct.image_url,\n        openai,'), 'Admin single-product regeneration must use GPT Image typography.');
assert(adminCarouselRegenerate.includes('sourceImageUrl: product.image_url,\n      openai,'), 'Admin carousel regeneration must use GPT Image typography.');

console.log('v144.18 GPT Image transparent asset checks passed');
